        numberInQuran: 4021,
        juz: 23,
        page: 456,
        arab: "\u0645\u064f\u062a\u0651\u064e\u0643\u0650\u0626\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u0650\u0641\u064e\u0627\u0643\u0650\u0647\u064e\u0629\u064d \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u064d \u0648\u064e\u0634\u064e\u0631\u064e\u0627\u0628\u064d",
        transliteration: "Muttaki'eena feehaa yad'oona feehaa bifaakihatin kaseeratinw wa sharaab",
        translation: "di dalamnya mereka bersandar (di atas dipan-dipan) sambil meminta buah-buahan yang banyak dan minuman (di surga itu).",
        shortTafsir: "Di dalamnya mereka bersandar di atas dipan-dipan sambil meminta suguhan berupa buah-buahan yang banyak dan minuman dengan berbagai jenis dan rasa.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4021",
