        numberInQuran: 4023,
        juz: 23,
        page: 456,
        arab: "\u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0644\u0650\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u0650",
        transliteration: "Haaza maa too'odoona li Yawmil Hisaab",
        translation: "Inilah apa yang dijanjikan kepadamu pada hari perhitungan.",
        shortTafsir: "Inilah apa yang dijanjikan Allah kepadamu pada hari perhitungan, hari ketika manusia dibangkitkan dari kubur lalu diarak ke padang mahsyar dan diadili di hadapan Allah.",
