      Ayah(
        numberInSurah: 54,
        numberInQuran: 4024,
        juz: 23,
        page: 456,
        arab: "\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0631\u0650\u0632\u0652\u0642\u064f\u0646\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646 \u0646\u0651\u064e\u0641\u064e\u0627\u062f\u064d",
        transliteration: "Inna haazaa larizqunaa maa lahoo min nafaad",
        translation: "Sungguh, inilah rezeki dari Kami yang tidak ada habis-habisnya.",
        shortTafsir: "Sungguh, karunia besar dan mulia inilah rezeki dari Kami yang tidak ada habis-habisnya dan tidak pula berkurang. Kami berikan karunia itu kepada hamba-hamba yang taat dan berbakti.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4024",
      ),
      Ayah(
        numberInSurah: 55,
        numberInQuran: 4025,
        juz: 23,
        page: 456,
        arab: "\u0647\u064e\u0670\u0630\u064e\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0637\u0651\u064e\u0627\u063a\u0650\u064a\u0646\u064e \u0644\u064e\u0634\u064e\u0631\u0651\u064e \u0645\u064e\u0622\u0628\u064d",
        transliteration: "Haazaa; wa inna littaagheena lasharra ma-aab",
        translation: "Beginilah (keadaan mereka). Dan sungguh, bagi orang-orang yang durhaka pasti (disediakan) tempat kembali yang buruk,",
        shortTafsir: "Bila Allah menyediakan surga beserta segala kenikmatan di dalamnya bagi orang yang taat, maka Allah menyediakan jahanam bagi orang yang durhaka terhadap risalah Allah. Beginilah karunia Allah kepada orang-orang yang bertakwa. Dan sungguh, bagi orang-orang yang durhaka terhadap perintah Allah dan rasul-Nya di dunia pasti di akhirat nanti disediakan tempat kembali yang buruk.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4025",
      ),
      Ayah(
        numberInSurah: 56,
        numberInQuran: 4026,
        juz: 23,
        page: 456,
        arab: "\u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u064a\u064e\u0635\u0652\u0644\u064e\u0648\u0652\u0646\u064e\u0647\u064e\u0627 \u0641\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u0650\u0647\u064e\u0627\u062f\u064f",
        transliteration: "Jahannama yaslawnahaa fai'sal mihaad",
        translation: "(yaitu) neraka Jahanam yang mereka masuki; maka itulah seburuk-buruk tempat tinggal.",
        shortTafsir: "Itulah neraka Jahanam, tempat tinggal yang kelak akan mereka masuki; maka Jahanam itulah seburuk-buruk tempat tinggal.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4026",
      ),
      Ayah(
        numberInSurah: 57,
        numberInQuran: 4027,
        juz: 23,
        page: 456,
        arab: "\u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u064e\u0644\u0652\u064a\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0647\u064f \u062d\u064e\u0645\u0650\u064a\u0645\u064c \u0648\u064e\u063a\u064e\u0633\u0651\u064e\u0627\u0642\u064c",
        transliteration: "Haazaa falyazooqoohu hameemunw wa ghassaaq",
        translation: "Inilah (azab neraka), maka biarlah mereka merasakannya, (minuman mereka) air yang sangat panas dan air yang sangat dingin,",
        shortTafsir: "Inilah azab yang Allah janjikan kepada para pendurhaka, maka biarlah mereka merasakannya dan mengetahui betapa pedih azab itu. Inilah air mendidih yang sangat panas dan membakar mulut, kerongkongan, serta usus mereka, dan air yang sangat dingin, yaitu nanah busuk dingin yang mengalir dari tubuh-tubuh penghuni neraka,",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4027",
      ),
      Ayah(
        numberInSurah: 58,
        numberInQuran: 4028,
        juz: 23,
        page: 456,
        arab: "\u0648\u064e\u0622\u062e\u064e\u0631\u064f \u0645\u0650\u0646 \u0634\u064e\u0643\u0652\u0644\u0650\u0647\u0650 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064c",
        transliteration: "Wa aakharu min shak liheee azwaaj",
        translation: "dan berbagai macam (azab) yang lain yang serupa itu.",
        shortTafsir: "dan di samping itu ada berbagai macam azab yang lain yang serupa pedihnya dengan azab itu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4028",
      ),
      Ayah(
        numberInSurah: 59,
        numberInQuran: 4029,
        juz: 23,
        page: 456,
        arab: "\u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u064e\u0648\u0652\u062c\u064c \u0645\u0651\u064f\u0642\u0652\u062a\u064e\u062d\u0650\u0645\u064c \u0645\u0651\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0644\u064e\u0627 \u0645\u064e\u0631\u0652\u062d\u064e\u0628\u064b\u0627 \u0628\u0650\u0647\u0650\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0635\u064e\u0627\u0644\u064f\u0648 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",
        transliteration: "Haazaa fawjum muqtahimum ma'akum laa marhabam bihim; innahum saalun Naar",
        translation: "(Dikatakan kepada mereka), \u201cIni rombongan besar (pengikut-pengikutmu) yang masuk berdesak-desak bersama kamu (ke neraka).\u201d Tidak ada ucapan selamat datang bagi mereka karena sesungguhnya mereka akan masuk neraka (kata pemimpin-pemimpin mereka).",
        shortTafsir: "Saat segolongan penghuni neraka memasukinya, dikatakan kepada mereka yang telah masuk neraka lebih dulu, \u201cIni rombongan besar pengikut-pengikutmu yang dahulu mau mengikuti ajakanmu menuju kedurhakaan. Mereka akan masuk dan berdesak-desak bersama kamu di neraka.\u201d Mereka yang masuk neraka lebih dulu berkata, \u201cTidak ada ucapan selamat datang apalagi penghormatan bagi mereka di neraka ini, karena sesungguhnya mereka akan masuk neraka dan disiksa bersama kami akibat perbuatan buruk yang mereka lakukan.\u201d (Lihat pula: Surah az-Zumar/38: 71\u201372).",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4029",
      ),
      Ayah(
        numberInSurah: 60,
        numberInQuran: 4030,
        juz: 23,
        page: 456,
        arab: "\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0644\u0652 \u0623\u064e\u0646\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u0645\u064e\u0631\u0652\u062d\u064e\u0628\u064b\u0627 \u0628\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0623\u064e\u0646\u062a\u064f\u0645\u0652 \u0642\u064e\u062f\u0651\u064e\u0645\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0644\u064e\u0646\u064e\u0627 \u06d6 \u0641\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0642\u064e\u0631\u064e\u0627\u0631\u064f",
        transliteration: "Qaaloo bal antum laa marhabam bikum; antum qaddamtumoohu lanaa fabi'sal qaraar",
        translation: "(Para pengikut mereka menjawab), \u201cSebenarnya kamulah yang (lebih pan-tas) tidak menerima ucapan selamat datang, karena kamulah yang menjerumuskan kami ke dalam azab, maka itulah seburuk-buruk tempat menetap.\u201d",
        shortTafsir: "Kelompok pengikut yang hendak masuk neraka itu menjawab \u201cSebenarnya kamulah yang lebih pantas untuk tidak menerima ucapan selamat datang dan penghormatan, karena kamulah yang menjerumuskan kami ke dalam azab neraka dengan mengajak kami berbuat dosa dan menghindari petunjuk Allah.\u201d Maka neraka itulah seburuk-buruk tempat menetap dan tempat kembali mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4030",
      ),
      Ayah(
        numberInSurah: 61,
        numberInQuran: 4031,
        juz: 23,
        page: 456,
        arab: "\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0645\u064e\u0646 \u0642\u064e\u062f\u0651\u064e\u0645\u064e \u0644\u064e\u0646\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u064e\u0632\u0650\u062f\u0652\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0636\u0650\u0639\u0652\u0641\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",
        transliteration: "Qaaloo Rabbanaa man qaddama lanaa haaza fazidhu 'azaaban di'fan fin Naar",
        translation: "Mereka berkata (lagi), \u201cYa Tuhan kami, barangsiapa menjerumuskan kami ke dalam (azab) ini, maka tambahkanlah azab kepadanya dua kali lipat di dalam neraka.\u201d",
        shortTafsir: "Demikianlah sergahan kelompok pengikut. Mereka berkata lagi seraya memohon kepada Allah, \u201cYa Tuhan kami, barang siapa mengajak kami memilih jalan kesesatan dan menjerumuskan kami ke dalam azab yang pedih dan berat ini, maka tambahkanlah azab kepadanya dua kali lipat di dalam neraka dan timpakanlah laknat yang besar atas mereka.\" (Lihat pula: Surah al-A\u2018r\u00e0f/7: 38; al-Ahz\u00e0b/33: 67\u201368).",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4031",
      ),
      Ayah(
        numberInSurah: 62,
        numberInQuran: 4032,
        juz: 23,
        page: 457,
        arab: "\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u0646\u064e\u0631\u064e\u0649\u0670 \u0631\u0650\u062c\u064e\u0627\u0644\u064b\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0639\u064f\u062f\u0651\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0634\u0652\u0631\u064e\u0627\u0631\u0650",
        transliteration: "Wa qaaloo ma lanaa laa naraa rijaalan kunnaa na'udduhum minal ashraar",
        translation: "Dan (orang-orang durhaka) berkata, \u201cMengapa kami tidak melihat orang-orang yang dahulu (di dunia) kami anggap sebagai orang-orang yang jahat (hina).",
        shortTafsir: "Para pendurhaka itu lalu berbicara dan saling bertanya-tanya seraya berkata, \u201cMe-ngapa kami tidak melihat orang-orang yang di dunia dahulu kami anggap sebagai orang-orang yang jahat, hina, buruk, dan bodoh, seperti Bilal, Suhaib, dan Ammar?\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4032",
      ),
      Ayah(
        numberInSurah: 63,
        numberInQuran: 4033,
        juz: 23,
        page: 457,
        arab: "\u0623\u064e\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0633\u0650\u062e\u0652\u0631\u0650\u064a\u0651\u064b\u0627 \u0623\u064e\u0645\u0652 \u0632\u064e\u0627\u063a\u064e\u062a\u0652 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f",
        transliteration: "Attakhaznaahum sikh riyyan am zaaghat 'anhumul absaar",
        translation: "Dahulu kami menjadikan mereka olok-olokan, ataukah karena penglihatan kami yang tidak melihat mereka?\u201d",
        shortTafsir: "Dahulu kami menjadikan mereka olok-olokan; apakah karena mereka tidak pantas menerima hinaan itu sehingga tidak masuk neraka bersama kami, ataukah karena penglihatan kami yang tidak melihat mereka di tempat ini lantaran mereka telah masuk lebih dulu?\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4033",
      ),
      Ayah(
        numberInSurah: 64,
        numberInQuran: 4034,
        juz: 23,
        page: 457,
        arab: "\u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u062d\u064e\u0642\u0651\u064c \u062a\u064e\u062e\u064e\u0627\u0635\u064f\u0645\u064f \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",
        transliteration: "Inna zaalika lahaqqun takhaasumu Ahlin Naar",
        translation: "Sungguh, yang demikian benar-benar terjadi, (yaitu) pertengkaran di antara penghuni neraka.",
        shortTafsir: "Sungguh, yang demikian itu benar-benar terjadi; itulah pertengkaran, saling mencaci, menyalahkan, dan menuduh di antara para penghuni neraka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4034",
      ),
      Ayah(
        numberInSurah: 65,
        numberInQuran: 4035,
        juz: 23,
        page: 457,
        arab: "\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0645\u064f\u0646\u0630\u0650\u0631\u064c \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0648\u064e\u0627\u062d\u0650\u062f\u064f \u0627\u0644\u0652\u0642\u064e\u0647\u0651\u064e\u0627\u0631\u064f",
        transliteration: "Qul innamaaa ana munzirunw wa maa min ilaahim illal laahul Waahidul Qahhaar",
        translation: "Katakanlah (Muhammad), \u201cSesungguhnya aku hanya seorang pemberi peringatan, tidak ada tuhan selain Allah Yang Maha Esa, Mahaperkasa,",
        shortTafsir: "Sebetulnya para penghuni neraka itu di dunia dahulu telah menerima peringatan para rasul untuk mengesakan Allah dan menaati aturan-Nya. Katakanlah, wahai Nabi Muhammad kepada kaum musyrik, \u201cSesungguhnya aku hanya seorang pemberi peringatan. Adalah tugasku untuk menyampaikan kepadamu ancaman-Nya yang pedih bagi orang-orang yang mengingkari-Nya. Karena itu, yakinilah bahwa tidak ada Tuhan yang berhak disembah selain Allah. Dialah Yang Maha Esa dan tidak ada sekutu bagi-Nya, Mahaperkasa sehingga dapat mengalahkan siapa pun yang menentang-Nya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4035",
      ),
      Ayah(
        numberInSurah: 66,
        numberInQuran: 4036,
        juz: 23,
        page: 457,
        arab: "\u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u063a\u064e\u0641\u0651\u064e\u0627\u0631\u064f",
        transliteration: "Rabbus samaawaati wal ardi wa maa bainahumal 'Azeezul Ghaffaar",
        translation: "(yaitu) Tuhan langit dan bumi dan apa yang ada di antara keduanya, Yang Mahaperkasa, Maha Pengampun.\u201d",
        shortTafsir: "Dialah Tuhan Pencipta langit dan bumi dan apa yang ada di antara keduanya. Dia menciptakan, menguasai, mengatur, mengawasi, dan memelihara kelangsungan ciptaan-Nya. Dialah Yang Mahaperkasa dalam mengatur kerajaan-Nya, Maha Pengampun atas dosa-dosa hamba yang memohon ampunan-Nya.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4036",
      ),
      Ayah(
        numberInSurah: 67,
        numberInQuran: 4037,
        juz: 23,
        page: 457,
        arab: "\u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0646\u064e\u0628\u064e\u0623\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",
        transliteration: "Qul huwa naba'un 'azeem",
        translation: "Katakanlah, \u201cItu (Al-Qur'an) adalah berita besar,",
        shortTafsir: "Wahai Nabi Muhammad, katakanlah kepada orang-orang kafir, \u201cAjakanku mengesakan Allah dan peringatanku tentang siksa akhirat itu adalah berita besar",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4037",
      ),
      Ayah(
