        numberInQuran: 4038,
        juz: 23,
        page: 457,
        arab: "\u0623\u064e\u0646\u062a\u064f\u0645\u0652 \u0639\u064e\u0646\u0652\u0647\u064f \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e",
        transliteration: "Antum 'anhu mu'ridoon",
        translation: "yang kamu berpaling darinya.",
        shortTafsir: "yang selama ini kamu berpaling darinya, wahai orang-orang kafir. Berita dalam Al-Qur\u2019an itu benar adanya, tetapi banyak manusia mengingkari.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4038",
      ),
      Ayah(
        numberInSurah: 69,
        numberInQuran: 4039,
        juz: 23,
        page: 457,
        arab: "\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u064a\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u064d \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0625\u0650 \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0644\u064e\u0649\u0670 \u0625\u0650\u0630\u0652 \u064a\u064e\u062e\u0652\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Maa kaana liya min 'ilmim bilmala il a'laaa iz yakhtasimoon",
        translation: "Aku tidak mempunyai pengetahuan sedikit pun tentang al-mala\u2019ul a\u2019la (malaikat) itu ketika mereka berbantah-bantahan.",
        shortTafsir: "Katakanlah pula kepada mereka, \u201cAku tidak mempunyai pengetahuan sedikit pun tentang al-mala\u2019ul a\u2018l\u00e0 itu, yaitu malaikat, ketika mereka berbantah-bantahan terhadap keputusan Allah terkait penciptaan Nabi Adam sebagai khalifah di bumi.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4039",
      ),
      Ayah(
        numberInSurah: 70,
        numberInQuran: 4040,
        juz: 23,
        page: 457,
        arab: "\u0625\u0650\u0646 \u064a\u064f\u0648\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",
        transliteration: "Iny-yoohaaa ilaiya illaaa annnamaaa ana nazeerum mubeen",
        translation: "Yang diwahyukan kepadaku, bahwa aku hanyalah seorang pemberi peringatan yang nyata.\u201d",
        shortTafsir: "Yang diwahyukan kepadaku hanyalah kepastian bahwa aku hanyalah seorang rasul pemberi peringatan dan petunjuk yang nyata tentang adanya siksa di akhirat bagi orang-orang yang mengingkari para utusan Allah.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4040",
      ),
      Ayah(
        numberInSurah: 71,
        numberInQuran: 4041,
        juz: 23,
        page: 457,
        arab: "\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u0650\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u062e\u064e\u0627\u0644\u0650\u0642\u064c \u0628\u064e\u0634\u064e\u0631\u064b\u0627 \u0645\u0651\u0650\u0646 \u0637\u0650\u064a\u0646\u064d",
        transliteration: "Iz qaala Rabbuka lilmalaaa'ikati innee khaaliqum basharam min teen",
        translation: "(Ingatlah) ketika Tuhanmu berfirman kepada malaikat, \u201cSesungguhnya Aku akan menciptakan manusia dari tanah.",
        shortTafsir: "Usai menafikan pengetahuan Rasulullah menyangkut al-Mala\u2019ul-A\u2018la kecuali apa yang sudah diwahyukan oleh Allah, pada ayat berikut Allah lalu menguraikan sekelumit tentang al-Mala\u2019ul-A\u2018la dan penciptaan Nabi Adam. Ingatlah ketika Tuhanmu berfirman kepada malaikat, \u201cSesungguhnya Aku akan menciptakan manusia Adam sebagai khalifah di bumi. Aku menciptakannya dari tanah bercampur air.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4041",
      ),
      Ayah(
        numberInSurah: 72,
        numberInQuran: 4042,
        juz: 23,
        page: 457,
        arab: "\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0648\u0651\u064e\u064a\u0652\u062a\u064f\u0647\u064f \u0648\u064e\u0646\u064e\u0641\u064e\u062e\u0652\u062a\u064f \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646 \u0631\u0651\u064f\u0648\u062d\u0650\u064a \u0641\u064e\u0642\u064e\u0639\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u0633\u064e\u0627\u062c\u0650\u062f\u0650\u064a\u0646\u064e",
        transliteration: "Fa-iza sawwaituhoo wa nafakhtu feehi mir roohee faqa'oo lahoo saajideen",
        translation: "Kemudian apabila telah Aku sempurnakan kejadiannya dan Aku tiupkan roh (ciptaan)-Ku kepadanya; maka tunduklah kamu dengan bersujud kepadanya.\u201d",
        shortTafsir: "Kemudian, apabila telah Aku sempurnakan kejadian fisik-nya dengan anggota tubuh dan bentuk yang sempurna dan Aku tiupkan roh ciptaan-Ku kepadanya, maka tunduklah kamu semua dengan bersujud penuh hormat kepadanya, bukan sujud penghambaan dan pengagungan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4042",
      ),
      Ayah(
        numberInSurah: 73,
        numberInQuran: 4043,
        juz: 23,
        page: 457,
        arab: "\u0641\u064e\u0633\u064e\u062c\u064e\u062f\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0643\u064f\u0644\u0651\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",
        transliteration: "Fasajadal malaaa'ikatu kulluhum ajma'oon",
        translation: "Lalu para malaikat itu bersujud semuanya,",
        shortTafsir: "Sempurnalah kejadian Adam, lalu dengan serta-merta para malaikat itu bersujud semuanya sebagai bentuk penghormatan kepadanya dan bukti ketaatan kepada perintah Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4043",
      ),
      Ayah(
        numberInSurah: 74,
        numberInQuran: 4044,
        juz: 23,
        page: 457,
        arab: "\u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0628\u0652\u0644\u0650\u064a\u0633\u064e \u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064e \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Illaaa Iblees; istakbara wa kaana minal kaafireen",
        translation: "kecuali Iblis; ia menyombongkan diri dan ia termasuk golongan yang kafir.",
        shortTafsir: "Mereka semua bersujud, kecuali Iblis; ia enggan bersujud di hadapan Adam karena menyombongkan diri dan enggan menaati kepada Allah, dan ia termasuk golongan yang kafir.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4044",
      ),
      Ayah(
        numberInSurah: 75,
        numberInQuran: 4045,
        juz: 23,
        page: 457,
        arab: "\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0625\u0650\u0628\u0652\u0644\u0650\u064a\u0633\u064f \u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e\u0643\u064e \u0623\u064e\u0646 \u062a\u064e\u0633\u0652\u062c\u064f\u062f\u064e \u0644\u0650\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064f \u0628\u0650\u064a\u064e\u062f\u064e\u064a\u0651\u064e \u06d6 \u0623\u064e\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u0652\u062a\u064e \u0623\u064e\u0645\u0652 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u0650\u064a\u0646\u064e",
        transliteration: "Qaala yaaa Ibleesu maa man'aka an tasjuda limaa khalaqtu biyadai; astakbarta am kunta min 'aaleen",
        translation: "(Allah) berfirman, \u201cWahai Iblis, apakah yang menghalangi kamu sujud kepada yang telah Aku ciptakan dengan kekuasaan-Ku. Apakah kamu menyombongkan diri atau kamu (merasa) termasuk golongan yang (lebih) tinggi?\u201d",
        shortTafsir: "Mengetahui hal tersebut Allah bertanya, \u201cWahai Iblis, apakah yang menghalangi kamu sujud dengan hormat kepada Adam yang telah Aku ciptakan dengan kekuasaan-Ku dan Aku muliakan? Apakah kamu menyombongkan diri dengan mengabaikan perintah-Ku atau kamu merasa termasuk golongan yang lebih tinggi dan terhormat daripada Adam?\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4045",
      ),
      Ayah(
        numberInSurah: 76,
        numberInQuran: 4046,
        juz: 23,
        page: 457,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u064e\u0627 \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0651\u0650\u0646\u0652\u0647\u064f \u06d6 \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064e\u0646\u0650\u064a \u0645\u0650\u0646 \u0646\u0651\u064e\u0627\u0631\u064d \u0648\u064e\u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064e\u0647\u064f \u0645\u0650\u0646 \u0637\u0650\u064a\u0646\u064d",
        transliteration: "Qaala ana khairum minah; khalaqtanee min naarinw wa khalaqtahoo min teen",
        translation: "(Iblis) berkata, \u201cAku lebih baik daripadanya, karena Engkau ciptakan aku dari api, sedangkan dia Engkau ciptakan dari tanah.\u201d",
        shortTafsir: "Iblis berkata, \u201cAku lebih baik daripadanya, karena Engkau ciptakan aku dari api, sedangkan dia Engkau ciptakan dari tanah.\u201d Iblis mengira api lebih baik daripada tanah karena api selalu membumbung sedangkan tanah selalu di bawah (Lihat pula: Surah al-A\u2018r\u00e0f/7: 12).",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4046",
      ),
      Ayah(
