        numberInQuran: 4047,
        juz: 23,
        page: 457,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0627\u062e\u0652\u0631\u064f\u062c\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0631\u064e\u062c\u0650\u064a\u0645\u064c",
        transliteration: "Qaala fakhruj minhaa fainnaka rajeem",
        translation: "(Allah) berfirman, \u201cKalau begitu keluarlah kamu dari surga! Sesungguhnya kamu adalah makhluk yang terkutuk.",
        shortTafsir: "Mengetahui kedurhakaan Iblis, Allah mengusirnya seraya berfirman, \u201cKalau begitu, keluarlah kamu dari surga! Sesungguhnya kamu adalah makhluk yang terkutuk, terusir dari rahmat-Ku, dan terlarang dari surga-Ku.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4047",
      ),
      Ayah(
        numberInSurah: 78,
        numberInQuran: 4048,
        juz: 23,
        page: 457,
        arab: "\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0644\u064e\u0639\u0652\u0646\u064e\u062a\u0650\u064a \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",
        transliteration: "Wa inna 'alaika la'nateee ilaa Yawmid Deen",
        translation: "Dan sungguh, kutukan-Ku tetap atasmu sampai hari pembalasan.\u201d",
        shortTafsir: "Dan sungguh, kutukan-Ku tetap berlaku atasmu sampai hari pembalasan, hari ketika seluruh perbuatan diperhitungkan dan dibalas.\u201d Iblis berkata seraya memohon,",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4048",
      ),
      Ayah(
        numberInSurah: 79,
        numberInQuran: 4049,
        juz: 23,
        page: 457,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0641\u064e\u0623\u064e\u0646\u0638\u0650\u0631\u0652\u0646\u0650\u064a \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u064a\u064f\u0628\u0652\u0639\u064e\u062b\u064f\u0648\u0646\u064e",
        transliteration: "Qaala Rabbi fa anzirneee ilaa Yawmi yub'asoon",
        translation: "(Iblis) berkata, \u201cYa Tuhanku, tangguhkanlah aku sampai pada hari mereka dibangkitkan.\u201d",
        shortTafsir: "\u201cYa Tuhanku, karena Engkau telah menjadikan aku makhluk-Mu yang terlaknat, maka tangguhkanlah kematianku dan izinkanlah aku hidup sampai pada hari mereka dibangkitkan supaya aku bisa menggoda mereka sepanjang hayat.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/4049",
      ),
      Ayah(
        numberInSurah: 80,
        numberInQuran: 4050,
        juz: 23,
        page: 457,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u0638\u064e\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Qaala fa innaka minal munzareen",
